// Neon silhouette: contour lines only, in palette slot 0, split into red, green and blue
// copies, with an echo that trails movement and fans the split out.
// param[0] echo, param[1] split, param[2] detail.
float aspect = resolution.x / resolution.y;
vec3 luma = vec3(0.299, 0.587, 0.114);

// Sobel step: a fixed fraction of the frame height, so the line keeps its width at any size.
vec2 px = vec2(1.0 / aspect, 1.0) * 0.0035;

// The split: a few thousandths of the frame height, kicked wider on the beat, slowly turning.
float spread = (0.003 + 0.022 * param[1]) * (1.0 + 1.8 * audio.beat);
float turn = 0.35 * sin(time * 0.4);
vec2 off = vec2(cos(turn) / aspect, sin(turn)) * spread;

// Only strong contours (detail low) up to every edge (detail high).
float thr = mix(1.4, 0.25, param[2]);

vec3 core = vec3(0.0);
vec3 halo = vec3(0.0);
for (int k = 0; k < 3; k++) {
  vec2 p = uv + off * float(1 - k);
  float tl = dot(source(p + px * vec2(-1.0, 1.0)), luma);
  float tc = dot(source(p + px * vec2(0.0, 1.0)), luma);
  float tr = dot(source(p + px * vec2(1.0, 1.0)), luma);
  float ml = dot(source(p + px * vec2(-1.0, 0.0)), luma);
  float mr = dot(source(p + px * vec2(1.0, 0.0)), luma);
  float bl = dot(source(p + px * vec2(-1.0, -1.0)), luma);
  float bc = dot(source(p + px * vec2(0.0, -1.0)), luma);
  float br = dot(source(p + px * vec2(1.0, -1.0)), luma);
  float gx = (tr + 2.0 * mr + br) - (tl + 2.0 * ml + bl);
  float gy = (tl + 2.0 * tc + tr) - (bl + 2.0 * bc + br);
  float g = length(vec2(gx, gy));
  core[k] = smoothstep(thr, thr * 1.5, g);
  halo[k] = smoothstep(thr * 0.4, thr * 1.2, g);
}

// The tube: a hot, whitened core inside a glow of the line colour. Each channel is taken from
// its own shifted copy, which is the split.
vec3 tube = palette[0];
vec3 hot = mix(tube, palette[1], 0.45);
float pump = 0.8 + 0.35 * audio.beat;
float flicker = 1.0 - 0.2 * audio.high * hash(vec2(floor(time * 24.0), 3.0));
vec3 fresh = (tube * halo * 0.9 + hot * core) * pump * flicker;

// The echo: the last frame fades, and each channel of it drifts a little further along the
// split, so a moving line leaves a trail and the split fans out behind it.
// echo 0 is none; 0.6 halves in about 14 frames (a quarter second at 60 fps); 1 lasts about
// half a second.
float decay = clamp(1.0 - 0.02 / pow(max(param[0], 0.01), 1.8), 0.0, 0.98);
vec2 drift = off * 0.12;
vec3 echo = vec3(lastFrame(uv + drift).r, lastFrame(uv).g, lastFrame(uv - drift).b) * decay;

// The glow: the last frame, spread a few pixels each frame on two rings that turn every frame
// (so they leave no pattern), so the tube bleeds light around it.
vec3 bloom = vec3(0.0);
float spin = hash(vec2(floor(time * 60.0), 7.0)) * 6.2832;
for (int i = 0; i < 6; i++) {
  float angle = spin + float(i) * 1.0472;
  float radius = (i % 2 == 0) ? 0.003 : 0.0065;
  bloom += lastFrame(uv + vec2(cos(angle) / aspect, sin(angle)) * radius);
}
bloom /= 6.0;

// Glow and echo meet in a max, never a sum: the feedback's gain stays below 1 and cannot build up.
vec3 neon = max(fresh + bloom * 0.8, echo);
vec3 room = source(uv) * clamp(1.0 - strength * 1.5, 0.0, 1.0);
return mix(room, max(room, neon), clamp(strength * 1.5, 0.0, 1.0));
